import { expect, it } from "vitest";
import { MemoryFileSystem } from "@poe-code/safe-fs/core";
import { runConvertCli, runConvertCliSync } from "./index.js";

// Six indexed colors with three distinct red samples, generated by ImageMagick.
const indexed = Buffer.from("", "base64");

for (const mode of ["sync", "buffered", "retained"] as const) {
    it.each([
        { input: ["xc:#0a1e46", "xc:#0a2846", "+append"], operation: ["-set", "colorspace", "Gray"], expected: "0a0a0aff" },
        { input: ["xc:#0a1e46", "xc:#0a2846", "+append"], operation: ["-colorspace", "Gray"], expected: "1d1d1dff242424ff" },
        { input: ["/in.png"], operation: ["-set", "colorspace", "Gray"], expected: "0a0a0aff141414ff1e1e1eff" },
    ])(`${mode}: extracts unique gray samples from $input with $operation`, async ({ input, operation, expected }) => {
        const files = new Map([["/in.png", indexed]]);
        const filesystem = new MemoryFileSystem();
        await filesystem.writeFile("/in.png", indexed);
        const args = [...input, ...operation, "-unique-colors", "-depth", "8", "rgba:/out"];
        const result = mode === "sync" ? runConvertCliSync(args, files)
            : await runConvertCli(args, mode === "buffered" ? files : { filesystem, cwd: "/" });
        expect({ exitCode: result.exitCode, stderr: result.stderr }).toEqual({ exitCode: 0, stderr: "" });
        const output = mode === "retained" ? await filesystem.readFile("/out") : files.get("/out")!;
        expect(Buffer.from(output).toString("hex")).toBe(expected);
    });
}
